    "chemeketa-rnbsn": {"prerequisites":[],"rules":{"gpa_overall_min":"not_published","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"none","selection":"lottery","points":"not_applicable","retakes":"not_published","local_priority":"In-district applicants (Marion, Polk, and Yamhill counties) are placed in the first lottery group; out-of-district applicants only if seats remain","seats":{"per_year":7,"applicants":"not_published","year":"Fall 2026 cohort","source_url":"https://www.chemeketa.edu/programs-classes/program-finder/nursing/rn-bsn-degree/"}},"wording":{"prerequisites":"Eligibility only: \"Completed an Associate of Applied Science (AAS) or Associate of Science (AS) in Nursing by Fall 2026\" and RN license by end of first term. In-program courses list STATS243 (for NUR314) and BI234 (for NUR414) as course prerequisites.","gpa":null,"exam":"No exam in the guide's eligibility requirements or application instructions.","selection":"\"Admission into the BSNCCC is lottery-based, with priority given to in-district residents.\"","points":null,"retakes":null,"local_priority":"\"In-District Applicants (Marion, Polk, and Yamhill counties) are placed in the first lottery group\"; out-of-district \"only be considered if seats remain unfilled\".","seats":"\"Seven (7) seats will be offered from each college in the consortium for a cohort of 42\""},"source_urls":["https://www.chemeketa.edu/programs-classes/program-finder/nursing/rn-bsn-degree/","https://www.chemeketa.edu/media/content-assets/documents/pdf/programs/health-sciences/nursing/bsn-degree/nursing_2026BSN_-BSNCCC_ApplicationGuideChemeketa.pdf"],"last_verified":"2026-11-26","academic_year":"Fall 2026 cohort (next cohort not yet posted)","deadline":"The page still lists the Fall 2026 window (June 1 - June 26, 2026, 5 pm), which has passed; next cohort dates not posted. Confirm with the school.","notes":"Requires an AAS or AS in Nursing and an unencumbered RN license by the end of the first term. Statistics (STATS243) and Microbiology (BI234) are listed as prerequisites to program courses NUR314 and NUR414, not as admission requirements. Consortium: LBCC, Chemeketa, Oregon Coast, Central Oregon, Treasure Valley, Klamath."},
