    "ohsu-bsn": {"prerequisites":[{"course":"Human Anatomy & Physiology with lab (full sequence, all body systems; 12 quarter / 8 semester credits) - first course","code":null,"category":"ap1","min_grade":"C-","within_years":7,"by_when":"see_text","one_of":null},{"course":"Human Anatomy & Physiology with lab (full sequence) - remaining course(s)","code":null,"category":"ap2","min_grade":"C-","within_years":7,"by_when":"start","one_of":null},{"course":"Microbiology with lab (4 quarter credits)","code":null,"category":"micro","min_grade":"C-","within_years":7,"by_when":"see_text","one_of":null},{"course":"Nutrition (3 quarter credits)","code":null,"category":"nutrition","min_grade":"C-","within_years":7,"by_when":"see_text","one_of":null},{"course":"Human development across the full lifespan (3 quarter credits)","code":null,"category":"lifespan","min_grade":"C-","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"English Composition I (part of 6 quarter credits)","code":"WR 121","category":"eng1","min_grade":"C-","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"English Composition II (part of 6 quarter credits)","code":"WR 122","category":"eng2","min_grade":"C-","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Social science electives (8 credits, including lifespan development credits)","code":null,"category":"other","min_grade":"C-","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Intermediate algebra / Math 95 or higher (or pass a proctored math competency test)","code":"MTH 95 or higher","category":"math","min_grade":"C-","within_years":"not_published","by_when":"see_text","one_of":null}],"rules":{"gpa_overall_min":"not_published","gpa_prereq_min":3,"gpa_science_min":"not_published","exam":"none","selection":"competitive","points":"not_applicable","retakes":{"counts":"see_text","max_attempts":"see_text","window_years":"see_text"},"local_priority":"Oregon residency is listed among factors that make an application stand out","seats":"not_published"},"wording":{"prerequisites":"\"You must earn a C- or better in each course.\" 28 quarter/19 semester prerequisite credits at application. Ashland, Monmouth, Portland: \"you must complete the following by the end of fall term\"; Klamath Falls, La Grande: \"by the end of winter term\". A&P: finish at least one course by end of fall term the year before; \"Complete all courses before starting\". A&P, micro, nutrition: \"no more than seven years prior to your intended start date.\" (7 years). Credits: A&P 12 quarter/8 semester; micro 4; nutrition 3; human development 3; English composition 6 (WR 121 and 122); social science electives 8.","gpa":"\"You need a minimum 3.0 prerequisite GPA.\"","exam":"No entrance exam listed. Math: \"Intermediate algebra/math 95 or higher: Pass a proctored competency test or complete qualifying math course\"","selection":"\"What we look for\": full A&P series and all prerequisites done by end of fall term, college chemistry with C- or better, credits from the campus host school (not Portland), a previous degree, life/health care experience (essay), Oregon residency, commitment to diverse communities, optional questionnaire. Interview dates are linked.","points":null,"retakes":"\"If you've taken a course more than once, we will use your most recent grade.\" A&P: take each course no more than twice in seven years; \"If you've taken a course more than twice in 7 years, we'll use your second attempt's grade.\"","local_priority":"Oregon residency listed under \"What we look for\".","seats":null},"source_urls":["https://www.ohsu.edu/school-of-nursing/3-year-bs-nursing-classes-and-requirements","https://www.ohsu.edu/school-of-nursing/admissions"],"last_verified":"2026-11-26","academic_year":"Fall 2027 admission","deadline":"Fall 2027: Portland Feb. 15, 2027; Ashland, Klamath Falls, La Grande, Monmouth priority Feb. 15, 2027, final April 15, 2027","notes":"Prerequisite completion deadline depends on campus: end of fall term (Ashland, Monmouth, Portland) or end of winter term (Klamath Falls, La Grande) before the fall start. Statistics courses count toward math only if from a math department with intermediate algebra prerequisite. No cumulative GPA minimum stated."},
